    return f(5)//(f(1)*f(4))*2**4 + f(5)//(f(1)*f(1)*f(3))*2**3 + f(5)//(f(3)*f(2))*2**2

def standard():
    from itertools import product
    sc = lambda x: x if x <= 4 else 0
    return sum(1 for t in product(range(1, 7), repeat=5) if sum(sc(x) for x in t) == 3)

def unique():
